from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}
        for i, x in enumerate(arr):
            total = 1
            for j in range(i):
                y = arr[j]
                if y * y > x:
                    break
                if x % y == 0:
                    z = x // y
                    if z in dp:
                        if z == y:
                            total += dp[y] * dp[y]
                        else:
                            total += 2 * dp[y] * dp[z]
            dp[x] = total % MOD
        return sum(dp.values()) % MOD
```

