from typing import List
import bisect

class Solution:
    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def f(s: str) -> int:
            return s.count(min(s))

        wf = sorted(f(w) for w in words)
        n = len(wf)
        res = []
        for q in queries:
            fq = f(q)
            idx = bisect.bisect_right(wf, fq)
            res.append(n - idx)
        return res
```

