Standard DP: for each stone, track the set of possible jump sizes that can land on it.

```python
from typing import List

class Solution:
    def canCross(self, stones: List[int]) -> bool:
        n = len(stones)
        if n == 1:
            return True
        if stones[1] != 1:
            return False
        # early exit: gap too large
        for i in range(1, n):
            if stones[i] - stones[i - 1] > i:
                return False
        pos = {s: set() for s in stones}
        pos[stones[0]].add(0)
        last = stones[-1]
        for s in stones:
            for k in pos[s]:
                for nk in (k - 1, k, k + 1):
                    if nk > 0:
                        nxt = s + nk
                        if nxt in pos:
                            if nxt == last:
                                return True
                            pos[nxt].add(nk)
        return len(pos[last]) > 0
```

