```python
from typing import List
from functools import lru_cache

class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        n = len(nums)
        # state: 2 bits per slot representing count of numbers placed in that slot (0,1,2)
        import sys
        sys.setrecursionlimit(10000)

        @lru_cache(maxsize=None)
        def dp(i: int, mask: int) -> int:
            if i == n:
                return 0
            best = 0
            for s in range(numSlots):
                cnt = (mask >> (2 * s)) & 3
                if cnt < 2:
                    new_mask = mask + (1 << (2 * s))
                    val = (nums[i] & (s + 1)) + dp(i + 1, new_mask)
                    if val > best:
                        best = val
            return best

        return dp(0, 0)
