class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def count_islands():
            seen = [[False] * n for _ in range(m)]
            cnt = 0
            for i in range(m):
                for j in range(n):
                    if grid[i][j] == 1 and not seen[i][j]:
                        cnt += 1
                        if cnt > 1:
                            return cnt
                        stack = [(i, j)]
                        seen[i][j] = True
                        while stack:
