from typing import List
from collections import defaultdict

class Solution:
    def minAreaRect(self, points: List[List[int]]) -> int:
        columns = defaultdict(list)
        for x, y in points:
            columns[x].append(y)
        last_x = {}
        best = float('inf')
        for x in sorted(columns):
            ys = sorted(columns[x])
            n = len(ys)
