class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        n = len(bloomDay)
        if m * k > n:
            return -1

        def can(day: int) -> bool:
            bouquets = 0
            run = 0
            for b in bloomDay:
