from itertools import combinations, permutations

class Solution:
    def nextBeautifulNumber(self, n: int) -> int:
        nums = set()
        digits = range(1, 8)
        for r in range(1, 8):
            for combo in combinations(digits, r):
                if sum(combo) > 7:
                    continue
                multiset = []
                for d in combo:
                    multiset.extend([d] * d)
                for p in set(permutations(multiset)):
                    nums.add(int("".join(map(str, p))))
        return min(x for x in nums if x > n)
