from typing import List

class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def feasible(limit: int) -> bool:
            count = 1
            current = 0
            for x in nums:
                if current + x > limit:
                    count += 1
                    current = x
                    if count > k:
                        return False
                else:
                    current += x
            return True

        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
```

