Classic bitmask DP: dp[mask] = min stickers to cover the set of target positions in mask. For each reachable mask, try each sticker and greedily assign its letters to uncovered target positions.

```python
from typing import List
from collections import Counter

class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        n = len(target)
        full = (1 << n) - 1
        target_set = set(target)
        # Preprocess stickers: keep only letters relevant to target; drop dominated stickers
        counters = []
        for s in stickers:
            c = Counter(ch for ch in s if ch in target_set)
            if c:
                counters.append(c)
        # Remove stickers that are subsets of others
        filtered = []
        for i, c in enumerate(counters):
            dominated = False
            for j, d in enumerate(counters):
                if i != j and all(d[k] >= v for k, v in c.items()) and (d != c or j < i):
                    dominated = True
                    break
            if not dominated:
                filtered.append(c)
        counters = filtered

        INF = float('inf')
        dp = [INF] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == INF:
                continue
            cur = dp[mask]
            for c in counters:
                cnt = dict(c)
                new_mask = mask
                for i in range(n):
                    if not (new_mask >> i) & 1:
                        ch = target[i]
                        v = cnt.get(ch, 0)
                        if v > 0:
                            cnt[ch] = v - 1
                            new_mask |= (1 << i)
                if new_mask != mask and dp[new_mask] > cur + 1:
                    dp[new_mask] = cur + 1
        return dp[full] if dp[full] != INF else -1
```

