from functools import lru_cache
from typing import List

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(maxsize=None)
        def dp(n, l, r):
            # normalize so that l + r <= n + 1
            if l + r > n + 1:
                l, r = n + 1 - r, n + 1 - l
            if l + r == n + 1:
                return (1, 1)
            m = (n + 1) // 2
            best_min = float('inf')
            best_max = float('-inf')
            if r <= n // 2 and r + r <= n:  # r in left half (opponent to the right of r)
                for i in range(l):
                    for j in range(r - l):
                        nl = i + 1
                        nr = i + j + 2
                        a, b = dp(m, nl, nr)
                        best_min = min(best_min, a + 1)
                        best_max = max(best_max, b + 1)
            else:
                # opponent of r is at n+1-r, strictly between l and r
                mid_count = 2 * r - n - 2
                s = (mid_count + 1) // 2
                between = n - r - l  # players strictly between l and n+1-r
                for i in range(l):
                    for j in range(between + 1):
                        nl = i + 1
                        nr = i + j + s + 2
                        a, b = dp(m, nl, nr)
                        best_min = min(best_min, a + 1)
                        best_max = max(best_max, b + 1)
            return (best_min, best_max)

        res = dp(n, firstPlayer, secondPlayer)
        return [res[0], res[1]]
