from typing import List
from collections import deque

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        indeg = [0] * n
        for i in range(n):
            for c in (leftChild[i], rightChild[i]):
                if c != -1:
                    indeg[c] += 1
                    if indeg[c] > 1:
                        return False
        roots = [i for i in range(n) if indeg[i] == 0]
        if len(roots) != 1:
            return False
        root = roots[0]
        seen = [False] * n
        seen[root] = True
        q = deque([root])
        count = 1
        while q:
            u = q.popleft()
            for c in (leftChild[u], rightChild[u]):
                if c != -1:
                    if seen[c]:
                        return False
                    seen[c] = True
                    count += 1
                    q.append(c)
        return count == n
